; Retr01 boot stub — generated by Studio Phase 5
; Assemble with ca65; Studio embeds an equivalent binary stub.
.setcpu "65C02"

SCROLL_PIXEL    = 0
SCROLL_DEADZONE = 1
SCROLL_INSTANT  = 2
SCROLL_HYBRID   = 3
XITION_CUT      = 0
XITION_FADE     = 1

C_PLAYER_META     = -1
C_ENEMY_ANIM_RATE = 8
C_ANIM_RATE       = 12
C_SCROLL_MODE     = 1
C_DEADZONE_X      = 48
C_DEADZONE_Y      = 45
C_TRANSITION      = 0
CART_HAS_I2C_SAVE = 0
START_WORLD       = 0

SCROLL_X  = $FE02
SCROLL_Y  = $FE03
WORLD     = $FE30

.segment "CODE"
.org $8000
reset:
        sei
        cld
        ldx #$ff
        txs
        lda #START_WORLD
        sta WORLD
        lda #0
        sta SCROLL_X
        sta SCROLL_Y
hang:
        jmp hang

.segment "VECTORS"
.org $FFFA
        .word hang
        .word reset
        .word hang
